use bitvm2_nova_script_oracle::wots::Result;

struct Pin {
    role: &'static str,
    args: &'static [i64],
    aliases: &'static [usize],
    sha256: &'static str,
}

fn validate(role: &str, args: &[i64]) -> Result<()> {
    if !matches!(role, "pallas_base" | "vesta_base")
        || !matches!(args, [1, 2, 3, 4] | [4, 4, 4, 4] | [3, 2, 1])
    {
        return Err("closed grouped arithmetic role/count pattern required".into());
    }
    Ok(())
}

pub fn frozen_row_body(count: usize) -> Result<Vec<u8>> {
    let row = count
        .checked_sub(1)
        .and_then(|index| ROWS.get(index))
        .ok_or("frozen conv_ab count must be1..4")?;
    Ok(hex::decode(row)?)
}

pub fn expected_raw_body_sha256(role: &str, args: &[i64]) -> Result<&'static str> {
    validate(role, args)?;
    PINS.iter()
        .find(|pin| pin.role == role && pin.args == args && pin.aliases.is_empty())
        .map(|pin| pin.sha256)
        .ok_or_else(|| "missing grouped raw body pin".into())
}

pub fn expected_body_sha256(role: &str, args: &[i64], aliases: &[usize]) -> Result<&'static str> {
    validate(role, args)?;
    let formal = args
        .iter()
        .map(|count| 2 * (*count as usize) + 1)
        .sum::<usize>();
    if aliases.len() != formal || aliases.is_empty() || aliases.len() > 36 {
        return Err("exact grouped formal alias framing required".into());
    }
    let mut next = 0usize;
    for alias in aliases {
        if *alias > next {
            return Err("first-occurrence aliases required".into());
        }
        if *alias == next {
            next += 1;
        }
    }
    if next > 15 {
        return Err("grouped unique operand cap exceeded".into());
    }
    PINS.iter()
        .find(|pin| pin.role == role && pin.args == args && pin.aliases == aliases)
        .map(|pin| pin.sha256)
        .ok_or_else(|| "closed grouped alias body has no pin".into())
}

